// Generated from content/help by scripts/help-index.mjs. Don't edit: change the .md files.
export const HELP_FILES: Record<string, string> = {
    "add-a-block": "---\ntitle: Add a block to a page\nsummary: Add a hero, services, gallery, form or any other block to a page.\narea: pages\norder: 2\nrelated: reorder-blocks, edit-copy-delete-a-block, block-background-and-spacing\npopular: true\n---\nBlocks are the building pieces of every page: a heading, a list of services, a gallery, a form.\n\n1. Open **Pages** and click the page you want to change. It opens in the editor.\n2. Click the block you want the new one to go under. New blocks are added below the selected one.\n3. In the left panel, open **Add a block**.\n4. Open a group, such as **Show what you do** or **Proof and people**, or type in **Find a block**.\n5. Click a block to add it, or drag it onto the page where you want it.\n6. Type into the new block’s settings on the right, then press **Publish**.\n\n![The block library in the editor](shot:editor-library)\n\n## Tips\n\n- Not sure what a block looks like? Press the **i** next to it, or try it first on the **Blocks** page.\n- Every block follows your theme’s colours and fonts automatically.\n",
    "add-a-form": "---\ntitle: Add a contact or quote form\nsummary: Put a form on any page so people can get in touch.\narea: forms\norder: 1\nrelated: change-form-questions, read-form-replies, add-a-block\npopular: true\n---\nEvery site starts with a contact form. Starter includes up to 3 forms, and Business and Studio up to 20.\n\n1. Open **Forms** and press **New form** if you need another one. Give it a **Form name**.\n2. Open the page you want it on in the editor.\n3. Under **Add a block**, open **Get in touch** and click **Form**.\n4. In the block’s settings, choose which form to show.\n5. Press **Publish**.\n\n## Tips\n\n- Replies arrive by email and in your **Forms** inbox. Change the email address in **Settings** under **Email for form replies**.\n- Forms are protected from spam automatically, with no puzzles for your visitors.\n",
    "add-a-page": "---\ntitle: Add a page\nsummary: Add a new page to your site, choose where it sits, and put it in your menu.\narea: pages\norder: 1\nrelated: add-a-block, reorder-blocks, page-in-menu-or-under-another\npopular: true\n---\nEvery page starts with a heading block, ready for you to add more.\n\n1. Open **Pages** in the sidebar.\n2. Press **New page** at the top right.\n3. Type the **Page title**, for example “Prices”. This becomes the page’s address too (/prices).\n4. If it belongs under another page, choose it in **Put it under**. Otherwise leave it as **Nothing (a main page)**.\n5. Press **Create and open**. The new page opens in the editor.\n6. Add blocks and words, then press **Publish** when you’re ready. Until then, visitors can’t see it.\n\n![The Pages screen with the New page form open](shot:pages-new)\n\n## Tips\n\n- New pages are added to your header menu automatically, unless you’ve set up your menus by hand. See [Edit your menus](help:edit-your-menus).\n- To add a page under an existing one straight from the list, press the **+** next to that page.\n- Not ready to share it? Leave it unpublished: it shows as a draft in your Pages list.\n",
    "add-a-project": "---\ntitle: Add a project to show your work\nsummary: Create a project page for a case study or piece of work.\narea: blog\norder: 4\nrelated: add-a-block, upload-pictures, write-a-blog-post\npopular: false\n---\n1. Open **Projects** in the sidebar.\n2. Type a **New project name** and press **Add project**. It opens in the page editor.\n3. Add the details, pictures and words, the same way as any page.\n4. Press **Publish**. It appears at /work/your-project, and in the **Projects** block on any page.\n\n![The Projects screen](shot:projects)\n\n## Tips\n\n- Use a **Gallery** or **Before and after** block to show the results.\n",
    "block-background-and-spacing": "---\ntitle: Change a block’s background and spacing\nsummary: Give a block a coloured background, more or less space, a fade-in, or a link name for menus.\narea: pages\norder: 5\nrelated: add-a-block, colours-and-fonts, edit-your-menus\npopular: false\n---\nEvery block has the same section options, at the bottom of its settings.\n\n1. Open the page in the editor and click the block.\n2. Scroll to the bottom of its settings on the right and open **Section: background, spacing, fade-in**.\n3. Choose a **Background**: page, soft, dark, your main colour or your accent colour.\n4. Choose **Space above and below**: compact, normal or roomy.\n5. Turn on **Fade in when scrolled to** if you’d like it to appear gently.\n6. Optionally type a **Link name**, like “pricing”, so a menu can jump straight to this block.\n\n![The section options for a block](shot:editor-section)\n\n## Tips\n\n- Text colours change automatically to stay readable on dark and coloured backgrounds.\n- Alternate between page and soft backgrounds to separate sections on a long page.\n",
    "buy-a-domain": "---\ntitle: Buy a domain\nsummary: Search for and buy a domain like yourbusiness.co.uk, connected for you.\narea: domains\norder: 1\nrelated: connect-your-domain, email-forwarding, choose-a-plan\npopular: true\n---\n1. Open **Domains** in the sidebar.\n2. Under **Buy a domain**, type the name you’d like and press **Search**.\n3. Pick an available one from the list and press **Buy**. You’ll pay securely by card.\n4. Slate registers it in your name and connects it to your site with HTTPS. This usually takes a few minutes.\n\n![Domain search results](shot:domains-search)\n\n## Tips\n\n- You need to have confirmed your email address before buying.\n- .co.uk is the most familiar ending for UK businesses.\n",
    "calendly-booking": "---\ntitle: Add Calendly booking\nsummary: Let people book a visit or call on your site.\narea: integrations\norder: 3\nrelated: whatsapp-button, add-a-block\npopular: false\n---\n1. Copy your scheduling link from Calendly.\n2. In Slate, open **Integrations** and the **Bookings** tab, then choose **Calendly**.\n3. Paste your **Calendly link** and save.\n4. Add a **Booking** block to the page where people should book (under **Get in touch** in the block library), then publish.\n",
    "change-form-questions": "---\ntitle: Change a form’s questions\nsummary: Add, remove or reorder questions, and change the message people see after sending.\narea: forms\norder: 2\nrelated: add-a-form, read-form-replies\npopular: false\n---\n1. Open **Forms**, choose the form and press **Edit form**.\n2. Press **Add a question**. Type its label and choose the **Answer type**: short text, long text, email, phone or a choice.\n3. For a choice, type the **Choices, one per line**.\n4. Tick **Must be filled in** for questions people have to answer.\n5. Change the **Button text** and the **Message after sending** if you like.\n6. Press **Save form**, then **Back to replies**.\n\n![Editing a form](shot:form-editor)\n\n## Tips\n\n- Shorter forms get more replies. Ask only what you need to give a quote or call back.\n",
    "change-roles": "---\ntitle: Change what someone can do\nsummary: Change a person’s role, or remove them from your site.\narea: people\norder: 2\nrelated: invite-someone\npopular: false\n---\n1. Open **People**.\n2. Next to the person, choose a new role, or press **Remove** to take away their access.\n\n## Roles\n\n- **Owner**: everything, including billing, domains and deleting the site.\n- **Admin**: everything except billing and deleting the site.\n- **Editor**: pages, blog, menus, forms and replies.\n- **Viewer**: can look at everything but not change it.\n",
    "choose-a-plan": "---\ntitle: Choose or change your plan\nsummary: Pick a plan before your trial ends, or move up or down later.\narea: account\norder: 1\nrelated: take-site-offline, download-everything\npopular: false\n---\n1. Open **Billing** in the sidebar.\n2. Press **Choose a plan** (or **Change plan** if you already have one).\n3. Choose monthly or yearly, and the plan you want.\n4. Pay securely by card. Your plan starts straight away.\n\n![The Billing screen](shot:billing)\n\n## Tips\n\n- Yearly costs the same as ten months.\n- Your invoices are listed under **Invoices**, ready to download as PDFs.\n- To stop paying, press **Cancel subscription**. Your site stays online until the end of the period you’ve paid for.\n",
    "colours-and-fonts": "---\ntitle: Change your colours and fonts\nsummary: Set your site’s colours and fonts once and every page follows.\narea: look\norder: 1\nrelated: logo-and-site-icon, header-and-footer, block-background-and-spacing\npopular: true\n---\n1. Open **Theme** in the sidebar.\n2. Under **Start from a palette**, pick a ready-made set of colours, or skip this step.\n3. Under **Colours**, set your main colour, accent, dark, soft and text colours. Click a swatch or type a colour code.\n4. Choose fonts for headings and text. The preview on the right updates as you go.\n5. Press **Save theme**. Your whole site changes straight away.\n\n![The Theme screen](shot:theme)\n\n## Tips\n\n- Pick a main colour with strong contrast against white, so buttons stay readable.\n- Changed your mind? Press **Discard changes** before saving.\n",
    "connect-your-domain": "---\ntitle: Connect a domain you already own\nsummary: Use a domain you bought elsewhere, without moving it.\narea: domains\norder: 2\nrelated: buy-a-domain, email-forwarding, redirects\npopular: false\n---\n1. Open **Domains** and press **Connect a domain**.\n2. Type your domain, like yourbusiness.co.uk, and press **Connect**.\n3. Slate shows the records to add. Log in to wherever you bought the domain and add them in its DNS settings.\n4. Back in Slate, press **Check again**. It shows **Waiting for records** until they’re found, then sets up HTTPS for you.\n\n![Connecting a domain](shot:domains-connect)\n\n## Tips\n\n- DNS changes can take from a few minutes to a few hours to be seen.\n- Keep your existing email records as they are; you only add the ones Slate shows.\n",
    "create-your-site": "---\ntitle: Create your site and pick a layout\nsummary: Sign up, name your business and choose a starting layout. Your site is live on a free address straight away.\narea: getting-started\norder: 1\nrelated: dashboard-tour, add-a-page, publish-changes\npopular: false\n---\nSigning up takes a couple of minutes, and you don’t need a card for the free trial.\n\n1. Go to [slatecms.co.uk/signup](/signup).\n2. Fill in **Your name**, **Email** and a **Password**.\n3. Under **What’s your business called?**, type your business name. It’s used for your site’s name and free address.\n4. Choose **Where’s your business based?**\n5. Pick the starting layout closest to your business, such as a trade, salon or shop. It gives you pages with blocks already in place. Choose blank if none fit.\n6. You land on your **Overview**. Your site is already live on its free address, shown at the top.\n\n## Tips\n\n- Nothing is fixed: you can rename, add or remove any page the layout gives you.\n- Check your inbox for the email asking you to confirm your address. You’ll need it confirmed before buying a domain.\n",
    "custom-page-not-found": "---\ntitle: Make your own “page not found” page\nsummary: Design the page visitors see when an address doesn’t exist, and your offline page.\narea: pages\norder: 10\nrelated: add-a-block, take-site-offline, redirects\npopular: false\n---\n1. Open **Pages** and scroll to **System pages**.\n2. Press **Edit** next to **Page not found**.\n3. Change it like any other page: add blocks, words and a button back to your home page.\n4. Press **Publish**.\n\n## Tips\n\n- The **Offline** system page is what visitors see while your site is offline. See [Take your site offline](help:take-site-offline).\n- System pages are hidden from search engines and menus automatically.\n",
    "dashboard-tour": "---\ntitle: A tour of the dashboard\nsummary: What each part of the Slate dashboard is for, from Overview to Billing.\narea: getting-started\norder: 2\nrelated: create-your-site, site-health, publish-changes\npopular: false\n---\nThe sidebar on the left takes you to every part of your site.\n\n![The Overview screen](shot:overview)\n\n1. Open **Overview** to see your live address, counts of pages, posts and form replies, and your site health score.\n2. Use the **Content** group for words and pictures: **Pages**, **Blog**, **Projects**, **Forms**, **Media** and **Menus**.\n3. Use the **Design** group for the look: **Theme** (colours, fonts, logo), **Layout** (header and footer) and **Blocks** (try every block).\n4. Use the **Site** group for everything else: **SEO**, **Domains**, **Integrations**, **People**, **Settings**, **Billing** and **Support**.\n5. To switch between sites, press **Switch** next to your site’s name at the top of the sidebar.\n\n## Tips\n\n- Every screen has a **Help with this page** link that opens the right part of this help centre.\n- The number next to **Forms** shows new replies waiting for you.\n",
    "describe-a-picture": "---\ntitle: Describe a picture (alt text)\nsummary: Add a short description so screen readers and Google know what’s in a picture.\narea: media\norder: 2\nrelated: upload-pictures, site-health\npopular: false\n---\n1. Open **Media** and click the picture.\n2. Type a few words in **Describe the image**, like “Green armchair after reupholstery”.\n3. Press **Save description**.\n4. Pictures in blocks also have a **Describe the image** box in the block’s settings.\n\n## Tips\n\n- Leave it empty only for decorative pictures that add nothing to the words.\n- Site health lists pictures on your pages that are missing a description.\n",
    "download-everything": "---\ntitle: Download everything\nsummary: Download a copy of your pages, posts, pictures and form replies.\narea: account\norder: 3\nrelated: take-site-offline, choose-a-plan\npopular: false\n---\n1. Open **Settings** in the sidebar.\n2. Under **People and your data**, press **Download a copy**.\n3. You get one file with your pages, blog posts, menus, settings, form replies as spreadsheets, and your pictures.\n\n## Tips\n\n- Owners and admins can download, because it includes every form reply.\n",
    "download-replies": "---\ntitle: Download replies as a spreadsheet\nsummary: Download every reply to a form as a CSV file for Excel or Google Sheets.\narea: forms\norder: 5\nrelated: read-form-replies, mark-replies-done\npopular: false\n---\n1. Open **Forms** and choose the form.\n2. Press **Download as CSV** above the list of replies.\n3. Open the file in Excel, Numbers or Google Sheets.\n",
    "edit-copy-delete-a-block": "---\ntitle: Edit, copy or delete a block\nsummary: Change a block’s words and pictures, duplicate it, or remove it.\narea: pages\norder: 4\nrelated: reorder-blocks, add-a-block, undo-and-page-history\npopular: false\n---\n1. Open the page in the editor and click the block.\n2. Its settings appear on the right. Type to change words; use **Choose image** to pick a picture. Changes save as you type.\n3. To copy the block, press the **two squares** icon in its toolbar. The copy appears underneath.\n4. To delete it, press the **bin** icon in its toolbar.\n5. Press **Publish** to make the changes live.\n\n## Tips\n\n- Deleted something by mistake? Press **Undo** at the top of the editor straight away.\n- Lists inside a block, like services or reviews, have **Add** buttons at the bottom of their settings, and a cross to remove each item.\n",
    "edit-your-menus": "---\ntitle: Edit your menus\nsummary: Change the links in your header and footer, add dropdowns and buttons.\narea: look\norder: 4\nrelated: page-in-menu-or-under-another, header-and-footer, add-a-page\npopular: true\n---\n1. Open **Menus** in the sidebar.\n2. Choose the menu: **Header**, **Footer** or **Footer small print**.\n3. Press **Add a link**. Type its **Text** and choose where it **Goes to**: one of your pages or any web address.\n4. Use the arrows to reorder links, or put one in a dropdown under the link above.\n5. Tick **Show as a button** to make a link stand out, or **Open in a new tab** for other websites.\n6. Press **Save menu**.\n\n![The Menus screen](shot:menus)\n\n## Tips\n\n- A button-style “Get a quote” link at the end of your header menu works well for most businesses.\n",
    "email-forwarding": "---\ntitle: Set up email forwarding\nsummary: Get emails sent to hello@yourbusiness.co.uk in the inbox you already use.\narea: domains\norder: 3\nrelated: buy-a-domain, connect-your-domain\npopular: false\n---\nFor domains bought through Slate.\n\n1. Open **Domains** and find your domain.\n2. Press **Email forwarding**.\n3. Type the **Address**, like “hello”, and where to **Send to**, like your Gmail address.\n4. Save it. Send a test email to check it arrives.\n\n## Tips\n\n- Add as many addresses as you like: hello@, bookings@, accounts@.\n- To reply from your business address, add it as a “send mail as” address in Gmail or Outlook.\n",
    "google-analytics": "---\ntitle: Add Google Analytics\nsummary: See who visits your site and where they come from.\narea: integrations\norder: 1\nrelated: google-search-console, whatsapp-button\npopular: false\n---\n1. In Google Analytics, create a property for your site and copy its **Measurement ID** (it starts with G-).\n2. In Slate, open **Integrations** and choose **Google Analytics**.\n3. Paste the **Measurement ID** and save.\n\n## Tips\n\n- Slate shows visitors a cookie choice automatically, as UK law needs for Google Analytics.\n- Want simple numbers without cookies? Slate’s built-in visitor stats are already on your Overview.\n",
    "google-search-console": "---\ntitle: Connect Google Search Console\nsummary: Prove to Google you own your site and see how it does in search.\narea: search\norder: 5\nrelated: titles-and-descriptions, site-health, google-analytics\npopular: false\n---\n1. Go to search.google.com/search-console and add your site as a **URL prefix** property.\n2. Choose the **HTML tag** method and copy it.\n3. In Slate, open **Integrations**, choose **Google Search Console** and paste it into **Verification code**.\n4. Save, then press **Verify** in Search Console.\n5. In Search Console, open **Sitemaps** and submit sitemap.xml.\n\n## Tips\n\n- If your domain is already verified with Google another way, you don’t need this. Site health spots it.\n",
    "header-and-footer": "---\ntitle: Change your header and footer\nsummary: Choose the header style, colours and footer for your whole site.\narea: look\norder: 3\nrelated: edit-your-menus, colours-and-fonts, logo-and-site-icon\npopular: false\n---\n1. Open **Layout** in the sidebar.\n2. Under **Header style**, choose **Standard**, **Centred** or **Mega menu**.\n3. Under **Header**, choose where it sits: **Above the page**, **See-through, on top of the first section**, or **Hidden**.\n4. Pick the header and footer colours.\n5. Press **Save layout**.\n\n![The Layout screen](shot:layout)\n\n## Tips\n\n- See-through headers look great over a hero with a picture.\n- To change the links themselves, see [Edit your menus](help:edit-your-menus).\n",
    "hide-or-delete-a-page": "---\ntitle: Hide a page from Google or delete it\nsummary: Keep a page out of search results, or remove it from your site.\narea: pages\norder: 9\nrelated: add-a-page, titles-and-descriptions, redirects\npopular: false\n---\n1. Open the page in the editor from **Pages**.\n2. With no block selected, the right panel shows **Page settings**.\n3. To keep it out of Google, tick **Hide this page from search engines**. People can still visit it with the link.\n4. To delete it, scroll to the bottom of **Page settings** and press **Delete this page…**, then **Delete page**.\n\n## Tips\n\n- If people or Google know the page’s address, add a redirect after deleting it, so they land somewhere useful. See [Add redirects](help:redirects).\n- Your home page and system pages can’t be deleted.\n",
    "invite-someone": "---\ntitle: Invite someone to help edit\nsummary: Give a colleague or your web designer their own login to your site.\narea: people\norder: 1\nrelated: change-roles, choose-a-plan\npopular: false\n---\n1. Open **People** in the sidebar.\n2. Optionally type **Their email** and **Name**.\n3. Choose their **Role**: owner, admin, editor or viewer. See **What each role can do** below the form.\n4. Press **Make invite link** and send them the link. They sign in or create an account and join your site.\n\n![The People screen](shot:people)\n\n## Tips\n\n- How many people you can add depends on your plan.\n",
    "logo-and-site-icon": "---\ntitle: Add your logo and site icon\nsummary: Add your logo to the header and the little icon shown in browser tabs.\narea: look\norder: 2\nrelated: colours-and-fonts, header-and-footer, upload-pictures\npopular: false\n---\n1. Open **Theme** in the sidebar.\n2. Under **Logo and icon**, press **Choose image** next to **Logo** and pick or upload your logo.\n3. Press **Choose image** next to the icon and choose a square picture. It appears in browser tabs and bookmarks.\n4. Press **Save theme**.\n\n## Tips\n\n- A logo with a transparent background (PNG or SVG) looks best on every header colour.\n- Use a simple square icon, at least 64 × 64 pixels. A single letter or mark works better than your full logo.\n- Change the logo size in **Layout**.\n",
    "mark-replies-done": "---\ntitle: Mark replies as done\nsummary: Keep your inbox tidy by marking replies done once you’ve dealt with them.\narea: forms\norder: 4\nrelated: read-form-replies, download-replies\npopular: false\n---\n1. Open a reply from **Forms**.\n2. Press **Mark as done**. It moves out of **To do**.\n3. Use the **To do**, **Done** and **All** tabs to switch between them.\n4. Press **Mark as unread** if you want to come back to one later.\n\n## Tips\n\n- Site health on your Overview reminds you about replies left waiting more than a week.\n",
    "page-in-menu-or-under-another": "---\ntitle: Put a page in the menu or under another page\nsummary: Choose where a page appears in your menu, or tuck it under another page in a dropdown.\narea: pages\norder: 6\nrelated: edit-your-menus, add-a-page, header-and-footer\npopular: false\n---\n1. When you add a page, choose its parent in **Put it under**. Pages under another page appear in a dropdown in the menu.\n2. To change it later, open **Menus** in the sidebar.\n3. Open the **Header** menu.\n4. Use the arrows to move links up or down, or **Put … in a dropdown under the link above** to nest one.\n5. Press **Save menu**.\n\n## Tips\n\n- Until you change your header menu by hand, Slate builds it from your pages automatically.\n- See [Edit your menus](help:edit-your-menus) to add links to other websites or show a link as a button.\n",
    "post-categories": "---\ntitle: Organise posts into categories\nsummary: Create categories and give each post one, so readers can browse by topic.\narea: blog\norder: 3\nrelated: write-a-blog-post, schedule-a-post\npopular: false\n---\n1. Open **Blog** in the sidebar.\n2. Under **Categories**, press **Add category**, type its **Category name** and press **Add**.\n3. Open a post, open **Post settings** and choose its **Category**.\n\n## Tips\n\n- A few broad categories work better than lots of narrow ones.\n",
    "preview-on-a-phone": "---\ntitle: Preview a page on a phone\nsummary: See how a page looks on a phone or tablet before you publish.\narea: pages\norder: 8\nrelated: publish-changes, add-a-block, block-background-and-spacing\npopular: false\n---\n1. Open the page in the editor from **Pages**.\n2. At the top of the editor, press **Phone**. The page shrinks to phone width.\n3. Scroll through and check the words and pictures fit well.\n4. Press **Tablet** to check a mid-sized screen, or **Desktop** to go back.\n\n![The editor showing a page at phone size](shot:editor-phone)\n\n## Tips\n\n- Most visitors to small business sites are on phones, so it’s worth checking every page this way.\n- If a heading wraps awkwardly on a phone, a shorter heading usually fixes it.\n",
    "publish-changes": "---\ntitle: Publish your changes\nsummary: Edits save as you go but stay private until you publish. Here’s how publishing works.\narea: getting-started\norder: 3\nrelated: undo-and-page-history, add-a-block, preview-on-a-phone\npopular: true\n---\nSlate keeps two versions of every page: your draft, which saves as you type, and the live version visitors see.\n\n1. Open a page from **Pages**.\n2. Make your changes. The top of the editor says **Draft saved. Not published yet.**\n3. Press **Publish** at the top right when you’re happy. Visitors see the new version straight away.\n4. Press **View live** to open the page on your site.\n\n## Tips\n\n- The **Pages** list shows **Unpublished changes** next to any page with edits visitors can’t see yet.\n- Theme, layout, menus and SEO changes go live as soon as you save them; only page content waits for **Publish**.\n- Every publish is kept. See [Undo a change or go back to an earlier version](help:undo-and-page-history).\n",
    "read-form-replies": "---\ntitle: Read and reply to form replies\nsummary: See every message from your forms and reply by email.\narea: forms\norder: 3\nrelated: mark-replies-done, download-replies, add-a-form\npopular: true\n---\n1. Open **Forms** in the sidebar. New replies are marked unread.\n2. Click a reply to read it.\n3. Press **Reply by email** to answer from your own email.\n4. Add a **Private note** if you want to remember something. Only people on your team can see it.\n\n![A form reply open in the inbox](shot:forms)\n\n## Tips\n\n- Use the search and sorting at the top to find an older reply.\n",
    "redirects": "---\ntitle: Add redirects when moving from another site\nsummary: Send people and Google from old addresses to your new pages.\narea: search\norder: 4\nrelated: site-health, connect-your-domain, titles-and-descriptions\npopular: false\n---\n1. Open **SEO** and scroll to **Redirects**.\n2. With **Add one**, type the **Old address**, like /old-page, and where to **Send people to**, like /services. Press **Add**.\n3. Moving lots of pages? Choose **Paste a list** and paste one per line: old address, a space, then the new one.\n4. Slate tells you about any lines it skipped and why.\n\n![Adding a redirect](shot:redirects)\n\n## Tips\n\n- Redirects are permanent, so Google moves your ranking to the new page.\n- Each redirect shows how many times it’s been used.\n",
    "reorder-blocks": "---\ntitle: Reorder blocks on a page\nsummary: Move blocks up and down a page with the arrows or by dragging.\narea: pages\norder: 3\nrelated: add-a-block, edit-copy-delete-a-block, publish-changes\npopular: true\n---\n1. Open the page in the editor from **Pages**.\n2. Click the block you want to move. A small toolbar appears above it.\n3. Press the **up arrow** or **down arrow** in the toolbar to move it one place at a time.\n4. Or drag it: hold the **dotted handle** at the left of the toolbar and drop the block where you want it.\n5. Press **Publish** when the order looks right.\n\n![A selected block with its toolbar](shot:editor-selected)\n\n## Tips\n\n- Made a mess? Press **Undo** (the curved arrow at the top) to step back.\n- To reorder items inside a block, like services or reviews, use the arrows next to each item in the settings on the right.\n",
    "schedule-a-post": "---\ntitle: Schedule a post for later\nsummary: Write a post now and have it go live on a date you choose.\narea: blog\norder: 2\nrelated: write-a-blog-post, post-categories, publish-changes\npopular: false\n---\n1. Open the post from **Blog**.\n2. Press **Schedule** instead of **Publish now**.\n3. Choose the date and time under **Publish on**.\n4. Press **Schedule post**. It shows as **Scheduled** in your Blog list until then.\n\n## Tips\n\n- Changed your mind? Open the post and press **Move to drafts**.\n",
    "send-replies-to-slack-or-mailchimp": "---\ntitle: Send replies to Slack, Discord or Mailchimp\nsummary: Get new replies in a chat channel, or add sign-ups to your email list.\narea: forms\norder: 6\nrelated: read-form-replies, google-analytics\npopular: false\n---\nAvailable on the Business and Studio plans.\n\n1. Open **Integrations** in the sidebar.\n2. Open the **Forms and email** tab.\n3. Choose **Slack**, **Discord**, **Mailchimp**, **Brevo** or **Webhook** and press it.\n4. Follow the steps on the card, such as pasting a Slack webhook address or connecting your Mailchimp list.\n5. Press **Save**. New replies are sent there from now on.\n\n![The Integrations screen](shot:integrations)\n",
    "share-images": "---\ntitle: Add a share image\nsummary: Choose the picture shown when someone shares your page on WhatsApp, Facebook or LinkedIn.\narea: search\norder: 2\nrelated: titles-and-descriptions, upload-pictures\npopular: false\n---\n1. Open **SEO** and click a page.\n2. Under **Share image**, press **Choose image** and pick a picture.\n3. Press **Save changes**.\n\n## Tips\n\n- The best size is 1200 × 630 pixels.\n- Set one under **Whole site** to use on every page that doesn’t have its own.\n",
    "site-health": "---\ntitle: Use Site health\nsummary: See your site’s health score and fix each item with one click.\narea: search\norder: 3\nrelated: titles-and-descriptions, describe-a-picture, redirects\npopular: true\n---\n1. Open **Overview** and press **Site health** to open it.\n2. The list shows what to improve, most important first: broken links, missing descriptions, big pictures and more.\n3. Each item names the page and block. Press **Fix** to go straight there.\n4. Fix it, publish or save, and the score goes up.\n\n![Site health on the Overview](shot:health)\n",
    "take-site-offline": "---\ntitle: Take your site offline\nsummary: Pause your site while you work on it. Visitors see your Offline page.\narea: account\norder: 2\nrelated: custom-page-not-found, download-everything\npopular: false\n---\n1. Open **Settings** in the sidebar.\n2. Under **Offline or delete**, press **Take offline**.\n3. Visitors now see your **Offline** page instead of your site.\n4. Press **Put back online** when you’re ready.\n\n![The Settings screen](shot:settings)\n\n## Tips\n\n- Design your Offline page from **Pages**, under **System pages**.\n",
    "titles-and-descriptions": "---\ntitle: Write page titles and descriptions for Google\nsummary: Set the title and description Google shows for each page.\narea: search\norder: 1\nrelated: share-images, site-health, google-search-console\npopular: true\n---\n1. Open **SEO** in the sidebar.\n2. Click a page in the list.\n3. Type the **Title in search results** and the **Description** (one or two sentences about the page).\n4. Watch the preview of how it could look on Google.\n5. Press **Save changes**. It goes live straight away.\n\n![The SEO screen](shot:seo)\n\n## Tips\n\n- Say what you do and where, like “Upholstery in Chester”.\n- Under **Whole site**, set a description used for any page without one.\n",
    "undo-and-page-history": "---\ntitle: Undo a change or go back to an earlier version\nsummary: Step back while editing, or restore any of the last 30 published versions of a page.\narea: pages\norder: 7\nrelated: publish-changes, edit-copy-delete-a-block, reorder-blocks\npopular: true\n---\n1. While editing, press **Undo** (the curved arrow at the top of the editor) to step back one change at a time.\n2. To go back further, press **History** at the top of the editor. You’ll see every time the page was published, who published it and a short summary.\n3. Press **Restore** next to the version you want. It goes back into your draft, so nothing changes on your site yet.\n4. Check it, then press **Publish** to make it live.\n\n![The History window](shot:editor-history)\n\n## Tips\n\n- Slate keeps the last 30 published versions of every page.\n- Restoring doesn’t delete anything: the version you replaced stays in the history too.\n",
    "upload-pictures": "---\ntitle: Upload pictures and files\nsummary: Add photos, logos and PDFs to use anywhere on your site.\narea: media\norder: 1\nrelated: describe-a-picture, add-a-block, logo-and-site-icon\npopular: false\n---\n1. Open **Media** in the sidebar.\n2. Press **Upload files** and choose one or more files. Or drag them onto the page.\n3. They appear in your library, ready to choose from any **Choose image** button.\n\n![The Media screen](shot:media)\n\n## Tips\n\n- Files can be up to 10 MB, but smaller is better: photos under 1 MB keep pages fast. Site health flags very large images.\n- You can also upload straight from any **Choose image** button in the editor.\n",
    "whatsapp-button": "---\ntitle: Add a WhatsApp button\nsummary: Add a “Message us” button to every page of your site.\narea: integrations\norder: 2\nrelated: calendly-booking, google-analytics\npopular: true\n---\n1. Open **Integrations** and the **Contact** tab.\n2. Press **WhatsApp**.\n3. Type your **WhatsApp number** and save.\n4. A “Message us” button appears on every page of your site.\n\n![Connecting WhatsApp](shot:integration-whatsapp)\n",
    "write-a-blog-post": "---\ntitle: Write and publish a blog post\nsummary: Write a post with a cover picture and publish it to your blog.\narea: blog\norder: 1\nrelated: schedule-a-post, post-categories, share-images\npopular: false\n---\n1. Open **Blog** in the sidebar and press **New post**.\n2. Type the **Title** and write the post. Leave a blank line between paragraphs.\n3. Open **Post settings** to add a **Cover image**, a short **Summary** and a **Category**.\n4. Press **Publish now**.\n\n![The Blog screen](shot:blog)\n\n## Tips\n\n- Start a line with “## ” for a heading and “- ” for a bullet point.\n- Your latest posts can appear on any page with the **Latest posts** block.\n"
}
